// ignore_for_file: file_names, avoid_print

// ============================================================================
// 02 — WHOAMI AND DIALOGS
// ============================================================================
//
// Lists your open chats (dialogs) — the same list you'd see scrolling
// Telegram's own chat list. Run 01_login.dart first so a session exists.
